'use client';

import {
  Toc as TocPrimitive,
  type UseTocProps,
  useToc as useTocPrimitive,
  useTocContext as useTocContextPrimitive,
} from '@ark-ui/react/toc';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { normalizeClassName } from '@/lib/moduix/normalizeClassName';
import styles from './Toc.module.css';

const railBaseOffset = 0;
const railStep = 12;
const railBridge = 6;
const maxRailLevel = 2;

const getRailOffset = (depth: number) =>
  railBaseOffset + Math.min(Math.max(depth - 2, 0), maxRailLevel) * railStep;

const useToc = ({ autoScroll = false, ...props }: UseTocProps) =>
  useTocPrimitive({ autoScroll, ...props });

const useTocContext = useTocContextPrimitive;

const TocRoot = forwardRef<
  ComponentRef<typeof TocPrimitive.Root>,
  ComponentProps<typeof TocPrimitive.Root>
>(function TocRoot({ autoScroll = false, className, ...props }, ref) {
  return (
    <TocPrimitive.Root
      ref={ref}
      autoScroll={autoScroll}
      data-slot="toc-root"
      className={clsx(styles.root, normalizeClassName(className))}
      {...props}
    />
  );
});

const TocRootProvider = forwardRef<
  ComponentRef<typeof TocPrimitive.RootProvider>,
  ComponentProps<typeof TocPrimitive.RootProvider>
>(function TocRootProvider({ className, style, value, ...props }, ref) {
  return (
    <TocPrimitive.RootProvider
      ref={ref}
      value={value}
      data-slot="toc-root-provider"
      className={clsx(styles.root, normalizeClassName(className))}
      style={{ ...value.getRootProps().style, ...style }}
      {...props}
    />
  );
});

const TocContent = forwardRef<
  ComponentRef<typeof TocPrimitive.Content>,
  ComponentProps<typeof TocPrimitive.Content>
>(function TocContent({ className, ...props }, ref) {
  return (
    <TocPrimitive.Content
      ref={ref}
      data-slot="toc-content"
      className={clsx(styles.content, normalizeClassName(className))}
      {...props}
    />
  );
});

const TocNav = forwardRef<
  ComponentRef<typeof TocPrimitive.Nav>,
  ComponentProps<typeof TocPrimitive.Nav>
>(function TocNav({ className, ...props }, ref) {
  return (
    <TocPrimitive.Nav
      ref={ref}
      data-slot="toc-nav"
      className={clsx(styles.nav, normalizeClassName(className))}
      {...props}
    />
  );
});

const TocTitle = forwardRef<
  ComponentRef<typeof TocPrimitive.Title>,
  ComponentProps<typeof TocPrimitive.Title>
>(function TocTitle({ className, ...props }, ref) {
  return (
    <TocPrimitive.Title
      ref={ref}
      data-slot="toc-title"
      className={clsx(styles.title, normalizeClassName(className))}
      {...props}
    />
  );
});

const TocList = forwardRef<
  ComponentRef<typeof TocPrimitive.List>,
  ComponentProps<typeof TocPrimitive.List>
>(function TocList({ className, ...props }, ref) {
  return (
    <TocPrimitive.List
      ref={ref}
      data-slot="toc-list"
      className={clsx(styles.list, normalizeClassName(className))}
      {...props}
    />
  );
});

const TocItem = forwardRef<
  ComponentRef<typeof TocPrimitive.Item>,
  ComponentProps<typeof TocPrimitive.Item>
>(function TocItem({ className, ...props }, ref) {
  return (
    <TocPrimitive.Item
      ref={ref}
      data-slot="toc-item"
      className={clsx(styles.item, normalizeClassName(className))}
      {...props}
    />
  );
});

const TocLink = forwardRef<
  ComponentRef<typeof TocPrimitive.Link>,
  ComponentProps<typeof TocPrimitive.Link>
>(function TocLink({ className, ...props }, ref) {
  return (
    <TocPrimitive.Link
      ref={ref}
      data-slot="toc-link"
      className={clsx(styles.link, normalizeClassName(className))}
      {...props}
    />
  );
});

const TocIndicator = forwardRef<
  ComponentRef<typeof TocPrimitive.Indicator>,
  ComponentProps<typeof TocPrimitive.Indicator>
>(function TocIndicator({ className, ...props }, ref) {
  return (
    <TocPrimitive.Indicator
      ref={ref}
      data-slot="toc-indicator"
      className={clsx(styles.indicator, normalizeClassName(className))}
      {...props}
    />
  );
});

type TocRailProps = ComponentProps<'svg'> & {
  depth: number;
  previousDepth?: number;
  nextDepth?: number;
};

const TocRail = forwardRef<SVGSVGElement, TocRailProps>(function TocRail(
  { className, depth, nextDepth = depth, previousDepth = depth, style, ...props },
  ref,
) {
  const lineOffset = getRailOffset(depth);
  const previousLineOffset = getRailOffset(previousDepth);
  const nextLineOffset = getRailOffset(nextDepth);
  const hasTurn = previousLineOffset !== lineOffset;
  const width = Math.max(previousLineOffset, lineOffset, nextLineOffset) + 2;

  return (
    <svg
      ref={ref}
      aria-hidden="true"
      data-slot="toc-rail"
      className={clsx(styles.rail, normalizeClassName(className))}
      style={{
        width,
        height:
          lineOffset === nextLineOffset
            ? `calc(100% + ${railBridge}px + var(--moduix-table-of-contents-list-gap, var(--moduix-spacing-0-5)))`
            : '100%',
        ...style,
      }}
      {...props}
    >
      {hasTurn && (
        <path
          d={`M ${previousLineOffset + 0.5} 0 C ${previousLineOffset + 0.5} 8 ${lineOffset + 0.5} 4 ${lineOffset + 0.5} ${railBridge * 2}`}
          fill="none"
          vectorEffect="non-scaling-stroke"
          stroke="currentColor"
        />
      )}
      <line
        x1={lineOffset + 0.5}
        y1={hasTurn ? railBridge * 2 : railBridge}
        x2={lineOffset + 0.5}
        y2="100%"
        vectorEffect="non-scaling-stroke"
        stroke="currentColor"
      />
    </svg>
  );
});

const Toc = Object.assign(TocRoot, {
  Root: TocRoot,
  RootProvider: TocRootProvider,
  Context: TocPrimitive.Context,
  Content: TocContent,
  Nav: TocNav,
  Title: TocTitle,
  List: TocList,
  Item: TocItem,
  Link: TocLink,
  Indicator: TocIndicator,
  Rail: TocRail,
});

export { Toc, useToc, useTocContext };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: grid;
    width: 100%;
    min-width: 0;
    grid-template-columns: minmax(0, 1fr) minmax(
        var(--moduix-table-of-contents-nav-min-width, 12rem),
        var(--moduix-table-of-contents-nav-width, 16rem)
      );
    gap: var(--moduix-table-of-contents-gap, var(--moduix-spacing-6));
    color: var(--moduix-table-of-contents-color, var(--moduix-color-foreground));
    /* Preserve Ark measurements when nested primitives also use --top or --height. */
    --_moduix-toc-indicator-top: var(--top);
    --_moduix-toc-indicator-height: var(--height);

    @media (max-width: 48rem) {
      grid-template-columns: minmax(0, 1fr);
    }
  }

  .content {
    min-width: 0;
    scroll-behavior: smooth;

    &:has(~ .nav[data-placement='left']) {
      grid-column: 2;
      grid-row: 1;
    }
  }

  .nav {
    position: sticky;
    top: var(--moduix-table-of-contents-nav-top, var(--moduix-spacing-4));
    align-self: start;
    max-height: var(--moduix-table-of-contents-nav-max-height, calc(100dvh - 2rem));
    overflow: auto;
    padding: var(--moduix-table-of-contents-nav-padding, var(--moduix-spacing-4));
    border: var(--moduix-table-of-contents-nav-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-table-of-contents-nav-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-table-of-contents-nav-radius, var(--moduix-radius-lg));
    background-color: var(--moduix-table-of-contents-nav-bg, var(--moduix-color-card));

    &[data-placement='left'] {
      grid-column: 1;
      grid-row: 1;
    }
  }

  .root:has(.nav[data-placement='left']) {
    grid-template-columns: minmax(
        var(--moduix-table-of-contents-nav-min-width, 12rem),
        var(--moduix-table-of-contents-nav-width, 16rem)
      ) minmax(0, 1fr);

    @media (max-width: 48rem) {
      .content:has(~ .nav[data-placement='left']),
      .nav[data-placement='left'] {
        grid-column: auto;
        grid-row: auto;
      }
    }
  }

  .title {
    margin: 0 0 var(--moduix-table-of-contents-title-margin-bottom, var(--moduix-spacing-2));
    color: var(--moduix-table-of-contents-title-color, var(--moduix-color-foreground));
    font-size: var(--moduix-table-of-contents-title-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-table-of-contents-title-font-weight, var(--moduix-weight-semibold));
    line-height: var(
      --moduix-table-of-contents-title-line-height,
      var(--moduix-line-height-text-sm)
    );
  }

  .list {
    position: relative;
    display: grid;
    gap: var(--moduix-table-of-contents-list-gap, var(--moduix-spacing-0-5));
    margin: 0;
    padding-block: 0;
    padding-inline-start: var(
      --moduix-table-of-contents-list-padding-start,
      var(--moduix-spacing-1)
    );
    list-style: none;

    &:has(.indicator)::before {
      position: absolute;
      top: var(--moduix-spacing-0-5);
      bottom: var(--moduix-spacing-0-5);
      inset-inline-start: 0;
      width: var(--moduix-table-of-contents-indicator-width, var(--moduix-border-width-md));
      border-radius: var(--moduix-radius-full);
      background-color: var(
        --moduix-table-of-contents-indicator-track-bg,
        var(--moduix-color-border)
      );
      content: '';
      pointer-events: none;
    }
  }

  .item {
    min-width: 0;
  }

  .link {
    position: relative;
    display: block;
    min-width: 0;
    padding-block: var(--moduix-table-of-contents-link-padding-y, var(--moduix-spacing-1));
    padding-inline-end: var(--moduix-table-of-contents-link-padding-x, var(--moduix-spacing-1));
    padding-inline-start: calc(
      var(--moduix-table-of-contents-link-padding-x, var(--moduix-spacing-1)) +
        var(--moduix-table-of-contents-indicator-width, var(--moduix-border-width-md)) +
        var(--moduix-spacing-2) +
        max(
          0px,
          calc(
            (var(--depth) - 2) *
              var(--moduix-table-of-contents-link-indent, var(--moduix-spacing-2))
          )
        )
    );
    overflow: hidden;
    border-radius: var(--moduix-table-of-contents-link-radius, var(--moduix-radius-sm));
    color: var(--moduix-table-of-contents-link-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-table-of-contents-link-font-size, var(--moduix-text-sm));
    line-height: var(
      --moduix-table-of-contents-link-line-height,
      var(--moduix-line-height-text-sm)
    );
    text-decoration: none;
    text-overflow: ellipsis;
    white-space: nowrap;
    outline: none;
    transition: color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        color: var(--moduix-table-of-contents-link-color-hover, var(--moduix-color-foreground));
      }
    }

    &:focus-visible {
      box-shadow: 0 0 0
        var(
          --moduix-table-of-contents-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
        var(--moduix-table-of-contents-focus-ring-color, var(--moduix-color-ring));
    }

    &[data-active] {
      color: var(--moduix-table-of-contents-link-color-active, var(--moduix-color-foreground));
      font-weight: var(
        --moduix-table-of-contents-link-font-weight-active,
        var(--moduix-weight-medium)
      );

      .rail {
        color: var(--moduix-table-of-contents-indicator-bg, var(--moduix-color-muted-foreground));
        opacity: 0.7;
        translate: 0 var(--moduix-spacing-0-5);
      }
    }

    &:has(.rail) {
      overflow: visible;
    }
  }

  .indicator {
    z-index: 1;
    top: calc(var(--_moduix-toc-indicator-top) + var(--moduix-spacing-0-5));
    inset-inline-start: 0;
    width: var(--moduix-table-of-contents-indicator-width, var(--moduix-border-width-md));
    height: calc(var(--_moduix-toc-indicator-height) - var(--moduix-spacing-1));
    border-radius: var(--moduix-table-of-contents-indicator-radius, var(--moduix-radius-full));
    background-color: var(
      --moduix-table-of-contents-indicator-bg,
      var(--moduix-color-muted-foreground)
    );
    opacity: 0.7;
    pointer-events: none;
    transition:
      top var(--moduix-transition-default),
      height var(--moduix-transition-default);
  }

  .rail {
    position: absolute;
    top: calc(-1 * var(--moduix-spacing-1-5));
    inset-inline-start: 0;
    overflow: visible;
    color: var(--moduix-table-of-contents-rail-color, var(--moduix-color-border));
    pointer-events: none;

    & :is(line, path) {
      stroke-width: var(--moduix-border-width-sm);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .content {
      scroll-behavior: auto;
    }

    .indicator {
      transition: none;
    }
  }
}
